function addEdgepoint(mx,my){
	let i=Edgepoints.length;
	let masspoint=new Masspoint(mx,my,5,i,0);
	Edgepoints.push(masspoint);
	if(i>0)
	{
		let edge=new Edge(Edgepoints[i-1],Edgepoints[i],i);
		Edges.push(edge);
	}
}

function addMasspoint(mx,my) {
	var masspoint=new Masspoint(mx,my,random(10,30),Masspoints.length,0);
	masspoint.applyForce(new p5.Vector(random(-1,1),random(-1,1)));
	Masspoints.push(masspoint);
}

function update(dt) {
	for(let i=0;i<Masspoints.length;i++)
	{
		Masspoints[i].update(dt);
	}
}

function inertia() {
	for(let i=0;i<Masspoints.length;i++)
	{
		Masspoints[i].inertia();
	}
}

function collide(preserve_impulse) {
	for(let i=0;i<Masspoints.length;i++)
	{
		for(let j=i+1;j<Masspoints.length;j++)
		{
			Masspoints[i].collide(Masspoints[j],preserve_impulse);
		}
		Masspoints[i].collideBorders(preserve_impulse);
	}
}

function drag(mx,my,masspoints) {
	for(let i=0;i<masspoints.length;i++)
	{
		masspoints[i].drag(mx,my);
	}
}

