class Masspoint
{
	constructor(x,y,dia,i,a)
	{
		this.location=createVector(x,y);
		this.lastLocation=createVector(x,y);
		this.acceleration=createVector(0,0);
		this.dragOffset=createVector(0,0);

		this.diameter=dia;
		this.radius=this.diameter/2;
		this.index=i;
		this.attractorIndex=a;

		this.momentOfInertia=PI*0.5*pow(this.radius,4);
		this.mass=this.momentOfInertia/10000;
		this.damping=0.99;

		this.pinned=false;
		this.dragging=false;

		this.Neighbours=[];
	}

	update(dt)
	{
		if(!this.pinned)
		{
			this.location.add(this.acceleration.mult(dt*dt));
			this.acceleration.mult(0);
		}
	}

	inertia()
	{
		if(!this.pinned)
		{
			let velocity=p5.Vector.sub(this.location, this.lastLocation);
			velocity.mult(this.damping);
			this.lastLocation.set(this.location);
			this.location.add(velocity);
		}
	}

	applyForce(force)
	{
		let f=p5.Vector.div(force,this.mass);
		this.acceleration.add(f);
	}

	registerNeighbour(other)
	{
		let distance=p5.Vector.sub(this.location, other.location);
		let dist=distance.magSq();
		let neighbour={index:other.index,distance:dist};
		this.Neighbours.push(neighbour);
		neighbour={index:this.index,distance:dist};
		other.Neighbours.push(neighbour);
	}

	connectToNeighbours(n)
	{
		// sort neighbours
		this.Neighbours.sort(sortDist);
		// check if n nearest neighbours are close enough
		for(let i=0;i<n;i++)
		{
			if(this.Neighbours.length>i)
			{
				let otherIndex=this.Neighbours[i].index;
				// check distance
				var distance=this.Neighbours[i].distance;
				if(distance<250*250)
				{
					if(this.bezierTouching && Masspoints[otherIndex].bezierTouching){
						//--------------------链接线条的颜色，要保持颜色数值的一致-----------------------
						pg.stroke(100);
						//--------------------链接线条的颜色，要保持颜色数值的一致-----------------------

						//--------------------链接线条的粗细，修改100*100后的两个数值----------------------
						let sw = map(distance,1*1,250*250,2,9,true);
						//--------------------链接线条的粗细，修改100*100后的两个数值----------------------

						pg.strokeWeight(sw);
						pg.line(this.location.x,this.location.y,Masspoints[otherIndex].location.x,Masspoints[otherIndex].location.y);
						pg.noStroke();
						//--------------------中心点颜色-------------------------------------------------
						pg.fill(100);
						//--------------------中心点颜色-------------------------------------------------

						pg.ellipse(this.location.x,this.location.y,this.diameter/10,this.diameter/10);
						pg.ellipse(Masspoints[otherIndex].location.x,Masspoints[otherIndex].location.y,Masspoints[otherIndex].diameter/10,Masspoints[otherIndex].diameter/10);
					}
					else{
						//--------------------链接线条的颜色，要保持颜色数值的一致-----------------------
						pg.stroke(100);
						//--------------------链接线条的颜色，要保持颜色数值的一致-----------------------
						//--------------------链接线条的粗细，修改250*250后的两个数值----------------------
						var sw = map(distance,1*1,250*250,2,9,true);
						//--------------------链接线条的粗细，修改250*250后的两个数值----------------------

						pg.strokeWeight(sw);
						pg.line(this.location.x,this.location.y,Masspoints[otherIndex].location.x,Masspoints[otherIndex].location.y);
						pg.noStroke();
						//--------------------中心点颜色-------------------------------------------------
						pg.fill(0);
						//--------------------中心点颜色-------------------------------------------------

						pg.ellipse(this.location.x,this.location.y,this.diameter/10,this.diameter/10);
						pg.ellipse(Masspoints[otherIndex].location.x,Masspoints[otherIndex].location.y,Masspoints[otherIndex].diameter/10,Masspoints[otherIndex].diameter/10);
					}
					// delete other.Neighbours.findIndex(index:this.index)...
					let nbi=Masspoints[otherIndex].Neighbours.indexOf('index'===otherIndex);
					Masspoints[otherIndex].Neighbours.splice(nbi, 1);
				}
			}
		}
		this.Neighbours.splice(0);
	}

	collide(other,preserve_impulse)
	{
		var distance=p5.Vector.sub(other.location, this.location);
		let distSq = distance.magSq();
		/*
		// Apply repelling force between Masspoints
		if(distSq < 5000 && !preserve_impulse)
		{
			let mag = map(distSq,0,5000,0.1,0,true);
			console.log('mag '+mag);
			let force=distance;
			this.applyForce(new p5.Vector.mult(force.normalize(),-mag/2));
			other.applyForce(new p5.Vector.mult(force.normalize(),mag/2));
		}
		*/
		// REGISTER NEIGHBOURS
		// ONLY ON 2ND COLLISION LOOP 
		if(preserve_impulse)
		{
			var neighbour={index:other.index,distance:distSq};
			this.Neighbours.push(neighbour);
			neighbour={index:this.index,distance:distSq};
			other.Neighbours.push(neighbour);
		}
		if(distSq <= (this.radius+other.radius)*(this.radius+other.radius) )
		{
			var dist=distance.mag();
			if(dist<this.radius+other.radius)
			{
				dist=this.radius+other.radius-dist;
				distance.normalize();
				distance.mult(dist*(this.mass/(this.mass+other.mass))+epsilon);
				other.location.add(distance);
				distance.normalize();
				distance.mult(-1*dist*(other.mass/(this.mass+other.mass))+epsilon);
				this.location.add(distance);
				if(preserve_impulse)
				{
					var distance=p5.Vector.sub(other.location, this.location);
					distance.normalize();
					let nd=new p5.Vector(-distance.y,distance.x);
					nd.normalize();

					let v1=p5.Vector.sub(this.location,this.lastLocation);
					let v2=p5.Vector.sub(other.location,other.lastLocation);
					let vt1=p5.Vector.mult(nd,p5.Vector.dot(v1,nd));
					let vt2=p5.Vector.mult(nd,p5.Vector.dot(v2,nd));
					let vn1=p5.Vector.mult(distance,p5.Vector.dot(v1,distance));
					let vn2=p5.Vector.mult(distance,p5.Vector.dot(v2,distance));

					this.lastLocation.set(this.location);
					this.lastLocation.sub(vt1);
					this.lastLocation.sub(vn2.mult(other.mass/(other.mass+this.mass)));
					other.lastLocation.set(other.location);
					other.lastLocation.sub(vt2);
					other.lastLocation.sub(vn1.mult(this.mass/(other.mass+this.mass)));
				}
			}
		}
	}

	collideBorders(preserve_impulse)
	{
		if(this.location.x > width-this.radius)
    {
      this.location.x = width-this.radius;

      if(preserve_impulse)
      {

        let n = new p5.Vector(1,0);
        var c = new p5.Vector(0,1);

        let v = p5.Vector.sub(this.location, this.lastLocation);
        // velocity of Bob in tangential direction
        let vt = p5.Vector.mult(c, p5.Vector.dot(v,c));
        // velocity of Bob in collision direction
        let vn = p5.Vector.mult(n, p5.Vector.dot(v,n));

        this.lastLocation.set(this.location);
        this.lastLocation.sub(vt.mult(1));
        this.lastLocation.add(vn);

      }
    }
		if(this.location.x < 0+this.radius)
    {
      this.location.x = 0+this.radius;

      if(preserve_impulse)
      {

        var n = new p5.Vector(-1,0);
        var c = new p5.Vector(0,-1);

        var v = p5.Vector.sub(this.location, this.lastLocation);
        // velocity of Bob in tangential direction
        var vt = p5.Vector.mult(c, p5.Vector.dot(v,c));
        // velocity of Bob in collision direction
        var vn = p5.Vector.mult(n, p5.Vector.dot(v,n));

        this.lastLocation.set(this.location);
        this.lastLocation.sub(vt.mult(1));
        this.lastLocation.add(vn);

      }
    }
		if(this.location.y > height-this.radius)
    {
      this.location.y = height-this.radius;

      if(preserve_impulse)
      {

        var n = new p5.Vector(0,1);
        var c = new p5.Vector(-1,0);

        var v = p5.Vector.sub(this.location, this.lastLocation);
        // velocity of Bob in tangential direction
        var vt = p5.Vector.mult(c, p5.Vector.dot(v,c));
        // velocity of Bob in collision direction
        var vn = p5.Vector.mult(n, p5.Vector.dot(v,n));

        this.lastLocation.set(this.location);
        this.lastLocation.sub(vt.mult(1));
        this.lastLocation.add(vn);

      }
    }
		if(this.location.y < 0+this.radius)
    {
      this.location.y = 0+this.radius;

      if(preserve_impulse)
      {

        var n = new p5.Vector(0,-1);
        var c = new p5.Vector(1,0);

        var v = p5.Vector.sub(this.location, this.lastLocation);
        // velocity of Bob in tangential direction
