  }


  changeParameters(p_P0, p_P1, p_P2, p_P3) {
    this.P0 = p_P0;
    this.P1 = p_P1;
    this.P2 = p_P2;
    this.P3 = p_P3;
  }


  evaluateDotProduct(M,t) {
		// ComplexNumber
    // result, perX, perY, tanX, tanY;
		// PVector 
		// M
		// double
    //divisor;

    let perX = t.pow(3).mult(-this.P3.x).addComplexNumber(t.mult(-1.0).add(1.0).multComplexNumber(t.pow(2)).mult(-3*this.P2.x)).addComplexNumber(t.mult(-1.0).add(1.0).pow(2).multComplexNumber(t).mult(-3*this.P1.x)).addComplexNumber(t.mult(-1.0).add(1.0).pow(3).mult(-this.P0.x)).add(M.x);
    let perY = t.pow(3).mult(-this.P3.y).addComplexNumber(t.mult(-1.0).add(1.0).multComplexNumber(t.pow(2)).mult(-3*this.P2.y)).addComplexNumber(t.mult(-1.0).add(1.0).pow(2).multComplexNumber(t).mult(-3*this.P1.y)).addComplexNumber(t.mult(-1.0).add(1.0).pow(3).mult(-this.P0.y)).add(M.y);
    let tanX = t.pow(2).mult(3*this.P3.x).addComplexNumber(t.mult(-1.0).add(1.0).multComplexNumber(t).mult(6*this.P2.x)).addComplexNumber(t.pow(2).mult(-3*this.P2.x)).addComplexNumber(t.mult(-1.0).add(1.0).multComplexNumber(t).mult(-6*this.P1.x)).addComplexNumber(t.mult(-1.0).add(1.0).pow(2).mult(3*this.P1.x)).addComplexNumber(t.mult(-1.0).add(1.0).pow(2).mult(-3*this.P0.x));
    let tanY = t.pow(2).mult(3*this.P3.y).addComplexNumber(t.mult(-1.0).add(1.0).multComplexNumber(t).mult(6*this.P2.y)).addComplexNumber(t.pow(2).mult(-3*this.P2.y)).addComplexNumber(t.mult(-1.0).add(1.0).multComplexNumber(t).mult(-6*this.P1.y)).addComplexNumber(t.mult(-1.0).add(1.0).pow(2).mult(3*this.P1.y)).addComplexNumber(t.mult(-1.0).add(1.0).pow(2).mult(-3*this.P0.y));
    let divisor = -3*this.P0.x*this.P0.x+18*this.P0.x*this.P1.x-18*this.P0.x*this.P2.x+6*this.P0.x*this.P3.x-27*this.P1.x*this.P1.x+54*this.P1.x*this.P2.x-18*this.P1.x*this.P3.x-27*this.P2.x*this.P2.x+18*this.P2.x*this.P3.x-3*this.P3.x*this.P3.x-3*this.P0.y*this.P0.y+18*this.P0.y*this.P1.y-18*this.P0.y*this.P2.y+6*this.P0.y*this.P3.y-27*this.P1.y*this.P1.y+54*this.P1.y*this.P2.y-18*this.P1.y*this.P3.y-27*this.P2.y*this.P2.y+18*this.P2.y*this.P3.y-3*this.P3.y*this.P3.y;
    //divisor = 1;

    let result = perX.multComplexNumber(tanX).addComplexNumber(perY.multComplexNumber(tanY)).divide(divisor);

    return result;
  }

  getNextGeneration(old, M) {
		// ComplexNumber[]
    var result = [];

    result[0] = this.evaluateDotProduct(M, old[0]).divideComplexNumber(old[0].addComplexNumber(old[1].mult(-1)).multComplexNumber(old[0].addComplexNumber(old[2].mult(-1))).multComplexNumber(old[0].addComplexNumber(old[3].mult(-1))).multComplexNumber(old[0].addComplexNumber(old[4].mult(-1)))).mult(-1).addComplexNumber(old[0]);
    result[1] = this.evaluateDotProduct(M, old[1]).divideComplexNumber(old[1].addComplexNumber(result[0].mult(-1)).multComplexNumber(old[1].addComplexNumber(old[2].mult(-1))).multComplexNumber(old[1].addComplexNumber(old[3].mult(-1))).multComplexNumber(old[1].addComplexNumber(old[4].mult(-1)))).mult(-1).addComplexNumber(old[1]);
    result[2] = this.evaluateDotProduct(M, old[2]).divideComplexNumber(old[2].addComplexNumber(result[1].mult(-1)).multComplexNumber(old[2].addComplexNumber(result[0].mult(-1))).multComplexNumber(old[2].addComplexNumber(old[3].mult(-1))).multComplexNumber(old[2].addComplexNumber(old[4].mult(-1)))).mult(-1).addComplexNumber(old[2]);
    result[3] = this.evaluateDotProduct(M, old[3]).divideComplexNumber(old[3].addComplexNumber(result[1].mult(-1)).multComplexNumber(old[3].addComplexNumber(result[2].mult(-1))).multComplexNumber(old[3].addComplexNumber(result[0].mult(-1))).multComplexNumber(old[3].addComplexNumber(old[4].mult(-1)))).mult(-1).addComplexNumber(old[3]);
    result[4] = this.evaluateDotProduct(M, old[4]).divideComplexNumber(old[4].addComplexNumber(result[1].mult(-1)).multComplexNumber(old[4].addComplexNumber(result[2].mult(-1))).multComplexNumber(old[4].addComplexNumber(result[3].mult(-1))).multComplexNumber(old[4].addComplexNumber(result[0].mult(-1)))).mult(-1).addComplexNumber(old[4]);

    return result;
  }


  getRootsOfDotProduct(M) {
    var result = [];

    result[0] = new ComplexNumber(1, 0);
    result[1] = new ComplexNumber(0.4, 0.9);
    result[2] = result[1].pow(2);
    result[3] = result[1].pow(3);
    result[4] = result[1].pow(4);

    for (let i = 0; i < 15; i++) {
      result = this.getNextGeneration(result, M);
    }

    return result;
  }


  getTClosestTo(M) {
    let roots = this.getRootsOfDotProduct(M);
    let tempResult = [];
    var result = [];
    let minDist = Number.MAX_VALUE;
    let threshold = 0.00001;

    for (let i = 0; i < 5; i++) {
      if (roots[i].Re() > 0 && roots[i].Re() < 1) {  
        tempResult.push(roots[i].Re());
      }
    }
    tempResult.push(0);
    tempResult.push(1);
    for (let i = 0; i < tempResult.length; i++) {
      var t = tempResult[i];
      var d = dist(M.x, M.y, bezierPoint(this.P0.x, this.P1.x, this.P2.x, this.P3.x, t), bezierPoint(this.P0.y, this.P1.y, this.P2.y, this.P3.y, t));
			if(d < minDist) {
        minDist = d;
      }
    }
    for (let i = 0; i < tempResult.length; i++) {
      var t = tempResult[i];
      var d = dist(M.x, M.y, bezierPoint(this.P0.x, this.P1.x, this.P2.x, this.P3.x, t), bezierPoint(this.P0.y, this.P1.y, this.P2.y, this.P3.y, t)) - minDist;
			if(abs(d) < threshold) {
        result.push(t);
      }
    }
    return result;
  }
}

class ComplexNumber {

  constructor(r, i) {
    this.rPart = r;
    this.iPart = i;
		if(typeof i === 'undefined'){
			this.iPart = 0;
		}
  }




  Re() {
    return this.rPart;
  }


  Im() {
    return this.iPart;
  }


  multComplexNumber(nb) {
    return new ComplexNumber(this.rPart * nb.Re() - this.iPart * nb.Im(), this.rPart * nb.Im() + this.iPart * nb.Re());
  }


  mult(lambda) {
    return new ComplexNumber(lambda * this.rPart, lambda * this.iPart);
  }


  addComplexNumber(nb) {
    return new ComplexNumber(this.rPart + nb.Re(), this.iPart + nb.Im());
  }

  add(lambda) {
    return new ComplexNumber(this.rPart + lambda, this.iPart);
  }


  divideComplexNumber(nb) {
    var divisor = nb.Re() * nb.Re() + nb.Im() * nb.Im();
    let dividendRe = this.rPart * nb.Re() + this.iPart * nb.Im();
    let dividendIm = this.iPart * nb.Re() - this.rPart * nb.Im();

    return new ComplexNumber(dividendRe / divisor, dividendIm / divisor);
  }


  divide(divisor) {
    return new ComplexNumber(this.rPart / divisor, this.iPart / divisor);
  }


  pow(n) {

    if (n == 0) {
      return new ComplexNumber(1, 0);
    }

    if (n == 1) {
      return new ComplexNumber(this.rPart, this.iPart);
    }

    var result = new ComplexNumber(this.rPart, this.iPart);   
    for (let i = 1; i < n - 1; i++) {
      result = result.multComplexNumber(this);
    }
    return result;
  }


  log() {
    println(this.rPart + " + " + this.iPart + "i");
  }
}

